220	            WasmValType::F32 => builder.ins().load(ir::types::F32, flags, addr, 0),
221	            WasmValType::F64 => builder.ins().load(ir::types::F64, flags, addr, 0),
222	            WasmValType::V128 => builder.ins().load(ir::types::I8X16, flags, addr, 0),
223	            WasmValType::Ref(r) => match r.heap_type.top() {
224	                WasmHeapTopType::Any | WasmHeapTopType::Extern | WasmHeapTopType::Exn => {
225	                    gc_compiler(func_env)?
