227	                }
228	                WasmHeapTopType::Func => {
229	                    let expected_ty = match r.heap_type {
230	                        WasmHeapType::Func => ModuleInternedTypeIndex::reserved_value(),
231	                        WasmHeapType::ConcreteFunc(ty) => ty.unwrap_module_type_index(),
232	                        WasmHeapType::NoFunc => {
233	                            let null = builder.ins().iconst(func_env.pointer_type(), 0);
234	                            if !r.nullable {
235	                                // Because `nofunc` is uninhabited, and this
236	                                // reference is non-null, this is unreachable
237	                                // code. Unconditionally trap via conditional
238	                                // trap instructions to avoid inserting block
239	                                // terminators in the middle of this block.
240	                                builder.ins().trapz(null, TRAP_INTERNAL_ASSERT);
241	                            }
242	                            return Ok(null);
243	                        }
244	                        _ => unreachable!("not a function heap type"),
245	                    };
246	                    let expected_ty = builder
247	                        .ins()
248	                        .iconst(ir::types::I32, i64::from(expected_ty.as_bits()));
249	
250	                    let vmctx = func_env.vmctx_val(&mut builder.cursor());
251	
252	                    let func_ref_id = builder.ins().load(ir::types::I32, flags, addr, 0);
253	                    let get_interned_func_ref = func_env
254	                        .builtin_functions
255	                        .get_interned_func_ref(builder.func);
256	
257	                    let call_inst = builder
258	                        .ins()
259	                        .call(get_interned_func_ref, &[vmctx, func_ref_id, expected_ty]);
260	                    builder.func.dfg.first_result(call_inst)
