    /// Emits an inline expansion of a copy of `len` bytes (a
    /// compile-time-constant) from `src` to `dst`, both of which are raw
    /// host-native addresses of type `self.pointer_type()`.
    ///
    /// The byte range is covered greedily using the widest available
    /// integer/vector type in the order `i8x16` (16 bytes), `i64` (8), `i32`
    /// (4), `i16` (2), `i8` (1). All chunk loads are emitted before any chunk
    /// stores so that overlapping source and destination ranges are copied
    /// correctly (i.e. `memmove` semantics).
    fn emit_inline_bulk_copy(
        &mut self,
        builder: &mut FunctionBuilder<'_>,
        dst: ir::Value,
        src: ir::Value,
        len: u64,
    ) {
        let pointer_type = self.pointer_type();
        assert_eq!(builder.func.dfg.value_type(dst), pointer_type);
        assert_eq!(builder.func.dfg.value_type(src), pointer_type);

        // Little-endian byte order is required for correctness here: the v128
        // (`i8x16`) load/store instructions only encode a little-endian variant
        // and will assert if given a big-endian flag on big-endian targets
        // (such as big-endian Pulley). The addresses have already been
        // bounds-checked so these accesses will not trap, but they may be
        // unaligned so the `aligned` flag is intentionally left unset.
        let flags = MemFlagsData::new()
            .with_notrap()
            .with_endianness(Endianness::Little);

        // Greedily decompose the byte range into chunks, widest type first.
        const CHUNKS: &[(ir::Type, u64)] = &[
            (I8X16, 16),
            (I64, 8),
            (I32, 4),
            (I16, 2),
            (I8, 1),
        ];
        let mut chunks = SmallVec::<[(ir::Type, i32); 16]>::new();
        let mut offset = 0;
        for &(ty, size) in CHUNKS {
            while len - offset >= size {
                chunks.push((ty, i32::try_from(offset).unwrap()));
                offset += size;
            }
        }
        debug_assert_eq!(offset, len);

        // Emit all loads before any stores so that overlapping ranges are
        // handled with `memmove` semantics.
        let mut loaded = SmallVec::<[ir::Value; 16]>::new();
        for &(ty, off) in &chunks {
            loaded.push(builder.ins().load(ty, flags, src, off));
        }
        for (&(_, off), &val) in chunks.iter().zip(&loaded) {
            builder.ins().store(flags, val, dst, off);
        }
    }

